from re import match

from taf.rfrl.procedures.resources.python.logger import log_env_state
from taf.rfrl.procedures.resources.python.sw_update.exceptions import InvalidSwVersion
from taf.rfrl.procedures.resources.python.sw_update.sw_version.sw_version import SwVersion

try:
    from urllib.request import urlopen
except ImportError:
    from urllib import urlopen


class GnbSwVersion(SwVersion):
    """ Represents 5G BTS software version """

    @property
    def package(self):
        """
        Returns SW version in package name format, i.e. 'AirScale-11.800.315.zip'

        :rtype: str
        """
        if self._package is None:
            self._package = 'AirScale-{}.zip'.format(self.simplified)
        return self._package

    @property
    def url(self):
        """
        Returns SW version in URL format, i.e.
        'https://artifactory-espoo1.int.net.nokia.com/artifactory/System_Release/11.800.315/AirScale-11.800.315.zip'

        :rtype: str
        """
        if self._url is None:
            self._url = 'https://artifactory-espoo1.int.net.nokia.com/artifactory/mnp5g-central-public-local/' \
                        'System_Release/{}/{}'.format(self.without_t_suffix.simplified, self.package)
            log_env_state(f'{self.__class__.__name__} url: {self._url}')
        return self._url

    @property
    def checksum(self):
        """
        Returns checksum of SW package.

        :rtype: str
        """
        if self._checksum is None:
            checksum_url = urlopen(self.url + ".md5")
            self._checksum = checksum_url.read().decode("UTF-8")

        return self._checksum

    def _validate_raw(self, raw):
        """
        Checks whether given raw SW version number is correct.

        :param raw: SW version in raw format, i.e. '5G21A_GNB_0011_000800_000315'
        :type raw: str
        :raises InvalidSwVersion: when given raw number is invalid
        """
        valid_raw_pattern = r'^5G[0-9A-B]{0,3}_GNB_[0-9]{4}_[0-9]{4,6}_[0-9]{6}T?[1-2]?$'

        if not match(valid_raw_pattern, raw):
            raise InvalidSwVersion('Cannot create {} from invalid raw input: {}'.format(self.__class__.__name__, raw))
